import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry } = ctx.THREE;
  const root = new Group();
  const resources = [];
  const timelines = [];
  const primitiveCleanups = [];
  let disposed = false;

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial();
  const backdropUv = uv();
  backdropMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    mix(
      vec3(0.086, 0.086, 0.114),
      vec3(0.906, 0.925, 0.949),
      smoothstep(0.48, 1.0, backdropUv.y)
    ),
    smoothstep(0.0, 0.62, backdropUv.y)
  );
  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  resources.push(backdropGeometry, backdropMaterial);

  const shadowGeometry = new PlaneGeometry(3.4, 1.9);
  const shadowMaterial = new MeshBasicNodeMaterial({
    color: '#0b0b10',
    transparent: true,
    opacity: 0.48
  });
  const shadow = new Mesh(shadowGeometry, shadowMaterial);
  shadow.position.set(0, -0.16, -0.22);
  shadow.scale.set(1.02, 0.42, 1);
  root.add(shadow);
  resources.push(shadowGeometry, shadowMaterial);

  const cardPivot = new Group();
  cardPivot.position.z = 0;
  root.add(cardPivot);

  const cardGeometry = new PlaneGeometry(2.9, 1.82);
  const cardMaterial = new MeshBasicNodeMaterial({
    color: '#e8ecf2'
  });
  const card = new Mesh(cardGeometry, cardMaterial);
  card.position.z = 0;
  cardPivot.add(card);
  resources.push(cardGeometry, cardMaterial);

  const backingGeometry = new BoxGeometry(2.98, 1.9, 0.08);
  const backingMaterial = new MeshBasicNodeMaterial({
    color: '#16161d'
  });
  const backing = new Mesh(backingGeometry, backingMaterial);
  backing.position.z = -0.07;
  cardPivot.add(backing);
  resources.push(backingGeometry, backingMaterial);

  const edgeMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38',
    transparent: true,
    opacity: 0.46
  });
  const edgePieces = [];

  const topEdge = new Mesh(new BoxGeometry(2.98, 0.035, 0.1), edgeMaterial);
  topEdge.position.set(0, 0.95, 0.02);
  const bottomEdge = new Mesh(new BoxGeometry(2.98, 0.035, 0.1), edgeMaterial);
  bottomEdge.position.set(0, -0.95, 0.02);
  const leftEdge = new Mesh(new BoxGeometry(0.035, 1.9, 0.1), edgeMaterial);
  leftEdge.position.set(-1.49, 0, 0.02);
  const rightEdge = new Mesh(new BoxGeometry(0.035, 1.9, 0.1), edgeMaterial);
  rightEdge.position.set(1.49, 0, 0.02);

  edgePieces.push(topEdge, bottomEdge, leftEdge, rightEdge);
  for (const edge of edgePieces) cardPivot.add(edge);
  resources.push(
    edgeMaterial,
    ...edgePieces.map((edge) => edge.geometry)
  );

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (disposed) return;
      if (ctx.THREE.SRGBColorSpace) texture.colorSpace = ctx.THREE.SRGBColorSpace;
      cardMaterial.map = texture;
      cardMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(cardPivot.position, {
    y: 0.15,
    duration: 0.42,
    ease: 'power3.out'
  });
  hoverTimeline.to(cardPivot.rotation, {
    x: -0.025,
    y: 0.035,
    duration: 0.3,
    ease: 'power2.out'
  }, 0);
  timelines.push(hoverTimeline);

  const pressTimeline = gsap.timeline({ paused: true });
  pressTimeline.to(cardPivot.scale, {
    x: 0.97,
    y: 0.97,
    z: 0.97,
    duration: 0.12,
    ease: 'power2.out'
  });
  pressTimeline.to(cardPivot.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.28,
    ease: 'back.out(2)'
  });
  timelines.push(pressTimeline);

  const focusTimeline = gsap.timeline({ paused: true });
  focusTimeline.to(edgeMaterial, {
    opacity: 1,
    duration: 0.22,
    ease: 'power2.out'
  });
  timelines.push(focusTimeline);

  const primitives = config.cinematicPrimitives ?? [];
  for (const primitive of primitives) {
    const apply = ctx.primitives?.[primitive.name];
    if (typeof apply === 'function') {
      const result = apply(root, primitive.params);
      if (result?.timeline) timelines.push(result.timeline);
      if (typeof result?.cleanup === 'function') {
        primitiveCleanups.push(result.cleanup);
      }
    }
  }

  root.userData.handlers = {
    hover: () => {
      if (disposed) return;
      hoverTimeline.play();
    },
    pointerout: () => {
      if (disposed) return;
      hoverTimeline.reverse();
    },
    click: () => {
      if (disposed) return;
      pressTimeline.restart();
      ctx.emit('hub-journal.select', { node: root });
    },
    focus: () => {
      if (disposed) return;
      focusTimeline.play();
    },
    blur: () => {
      if (disposed) return;
      focusTimeline.reverse();
    }
  };

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      if (timeline?.kill) timeline.kill();
    }

    for (const cleanup of primitiveCleanups) {
      cleanup();
    }

    for (const resource of resources) {
      if (resource?.dispose) resource.dispose();
    }

    root.clear();
  };

  return root;
}
